/* =====================================================================
   EMBEDDED FONTS (base64)
   Loads the "Tag" and "TagBig" fonts into the page. Data only - do not edit by hand.
   ===================================================================== */
(()=>{const L=(n,d)=>{try{const q=atob(d),u=new Uint8Array(q.length);for(let i=0;i<q.length;i++)u[i]=q.charCodeAt(i);new FontFace(n,u.buffer).load().then(f=>document.fonts.add(f)).catch(()=>{})}catch(_){}};L("Tag","");L("TagBig","")})();
